from functools import lru_cache
# use lattice positions where x=(pixel-36)//6, y=(pixel-18)//6
coords={'A':(3,0),'B':(3,1),'C':(3,2),'D':(2,3),'E':(1,4),'F':(0,5),'G':(1,5),'H':(2,5),'I':(2,6)}
start=frozenset(coords)
@lru_cache(None)
def solve(pegs):
    if len(pegs)==1:return []
    for p in pegs:
        x,y=p
        for dx in (-2,0,2):
            for dy in (-2,0,2):
                if (dx==0 and dy==0) or (dx!=0 and dy!=0 and abs(dx)!=abs(dy)):continue
                mid=(x+dx//2,y+dy//2); q=(x+dx,y+dy)
                if mid in pegs and q not in pegs:
                    np=(pegs-{p,mid})|{q}
                    r=solve(np)
                    if r is not None:return [(p,q)]+r
    return None
sol=solve(start)
sol

